// ── the specific shapes the subset must REFUSE ────────────────────────
//
// These are not soundness failures if admitted (the parser accepts them
// too) — they are the conservative exclusions the subset documents, and
// pinning them keeps a later widening deliberate rather than accidental.

const must_decline = [
	'[ns:name 1]', // QName — namespace resolution is not a no-op
	'[k::int 1]', // type tag
	'[k xmlns="http://x"]', // reserved namespace binding
	'[k a.b=1]', // dotted name
	'[k "has\\nescape"]', // escape decoding
	'[k bare text]', // bare body text folding
	'[k &anchor]', // anchor
	'[k #id]', // id declaration
	'[k *merge]', // merge
	'[k \$hole]', // hole
	'[k a, b]', // sequence literal
	'[k (1, 2)]', // paren sequence
	'[k {a: 1}]', // map literal
	'[k # comment\n]', // line comment
	'[k 007]', // non-canonical integer
	'[k 1e3]', // exponent
	'[k 5.]', // trailing dot
	'[k .5]', // leading dot
	'[k :atom]', // atom vs slot ambiguity
	'[k 2024-01-15]', // date
	'[k 1h30m]', // duration
	'[!DOCTYPE x]', // declaration
	'[?for 1]', // directive
	'[#raw#]', // raw text
]

fn test_documented_exclusions_decline() {
	for src in must_decline {
		if end := certified_span(src) {
			assert false, 'subset widened WITHOUT a decision: ${src} certified through ${end}'
		}
	}
	println('[child-scan] ${must_decline.len} documented exclusions all decline')
}

// ── the CANONICALITY obligation (804-1d, ruled 1a) ────────────────────
//
// The scan may declare a span canonical only when emitting that span —
// with its recorded delimiter rewrites applied — is byte-for-byte what
// the canonical renderer would produce:
//
//     canonical(span) ⇒ apply_rewrites(span) == render_canonical(parse(span))
//
// A false negative costs throughput. A false positive corrupts canonical
// output and every Tier-1 address derived from it, which is why the
// ruling made the predicate conservative and why this check is total
// rather than sampled. It runs over the same three corpora as soundness.

// canon_verdict returns (declared_canonical, matches_renderer).
fn canon_verdict(src string) (bool, bool) {
	bytes := src.bytes()
	sc := cx.scan_child_canonical(bytes, 0) or { return false, true }
	if !sc.canonical {
		return false, true
	}
	span := bytes[..sc.end]
	emitted := cx.apply_rewrites(span, 0, sc.rewrites)
	doc := cx.parse(src[..sc.end]) or { return true, false }
	if doc.elements.len != 1 {
		return true, false
	}
	return true, emitted == code.render_canonical(doc.elements[0])
}

fn assert_canonical_sound(src string, origin string) {
	declared, matches := canon_verdict(src)
	if declared && !matches {
		bytes := src.bytes()
		sc := cx.scan_child_canonical(bytes, 0) or { return }
		emitted := cx.apply_rewrites(bytes[..sc.end], 0, sc.rewrites)
		doc := cx.parse(src[..sc.end]) or { return }
		assert false, 'CANONICALITY FALSE POSITIVE — the span is NOT the canonical image\n' +
			'  origin  : ${origin}\n  span    : ${src[..sc.end]}\n' +
			'  emitted : ${emitted}\n  renderer: ${code.render_canonical(doc.elements[0])}'
	}
}

fn test_canonicality_never_false_positive() {
	mut declared := 0
	mut checked := 0
	files := os.ls(conformance_dir()) or {
		assert false, 'cannot list conformance dir'
		return
	}
	for f in files {
		if !f.ends_with('.cxd') {
			continue
		}
		path := os.join_path(conformance_dir(), f)
		for c in fixtures.load_fixtures(path) {
			src := c.sections['in_cx'].trim_space()
			if src == '' || src == '[ignored]' || src == '[empty]' {
				continue
			}
			checked++
			d, _ := canon_verdict(src)
			if d {
				declared++
			}
			assert_canonical_sound(src, '${f}/${c.name}')
		}
	}
	println('[child-scan] canonicality/conformance: ${checked} inputs, ${declared} declared canonical, 0 false positives')
}

fn test_canonicality_over_gate_corpus() {
	n := 3000
	mut declared := 0
	mut rewritten := 0
	for i in 0 .. n {
		r := gate_record(i)
		assert_canonical_sound(r, 'gate-15 record ${i}')
		bytes := r.bytes()
		sc := cx.scan_child_canonical(bytes, 0) or { continue }
		if sc.canonical {
			declared++
			if sc.rewrites.len > 0 {
				rewritten++
			}
		}
	}
	// This is the whole point of ruling 1a: the gate workload is
	// double-quoted, so a strict-identity predicate would score ZERO
	// here. If this regresses to 0 the delimiter rewrite has been lost
	// and the architecture's win with it.
	assert declared == n, 'gate-15: only ${declared}/${n} records declared canonical'
	assert rewritten == n, 'gate-15: only ${rewritten}/${n} records needed the delimiter rewrite — the corpus or the rule moved'
	println('[child-scan] canonicality/gate-15: ${declared}/${n} canonical, ${rewritten} via delimiter rewrite, 0 false positives')
}

fn test_canonicality_over_mutation_corpus() {
	mut cases := 0
	mut declared := 0
	for seed in mutation_seeds {
		for i in 0 .. seed.len {
			for mb in mutation_bytes {
				mutant := seed[..i] + mb.ascii_str() + seed[i + 1..]
				cases++
				d, _ := canon_verdict(mutant)
				if d {
					declared++
				}
				assert_canonical_sound(mutant, 'substitute @${i} in ${seed}')
			}
			del := seed[..i] + seed[i + 1..]
			cases++
			assert_canonical_sound(del, 'delete @${i} in ${seed}')
		}
	}
	assert cases > 5000, 'mutation corpus too small: ${cases}'
	println('[child-scan] canonicality/mutation: ${cases} mutants, ${declared} declared canonical, 0 false positives')
}

// The specific spellings the predicate must call NON-canonical. Each is
// well-formed (so the scan certifies it) but the renderer moves it, and
// each was measured against the renderer rather than assumed.
const must_not_be_canonical = [
	'[k ]', // trailing space before `]`
	'[k  1]', // double space between items
	'[k :s  1]', // double space inside a slot
	'[k\n 1]', // newline separator
	'[k -0]', // negative zero renders `0`
	'[k -0.0]', // negative zero decimal renders `0.0`
	'[k ""]', // empty string renders as nothing
	"[k '']", // ditto
	'[k a=1]', // attribute values render bare when safe
	'[k a="x"]', // ditto
	'[k "a\tb"]', // raw TAB is escaped `\t` in canonical text
	'[k "a\x01b"]', // other C0 controls become `\u00xx`
	'[k "a\x7fb"]', // DEL likewise
]

fn test_documented_non_canonical_spellings() {
	for src in must_not_be_canonical {
		bytes := src.bytes()
		sc := cx.scan_child_canonical(bytes, 0) or { continue }
		assert !sc.canonical, 'predicate widened WITHOUT a decision: ${src} declared canonical'
	}
	println('[child-scan] ${must_not_be_canonical.len} documented non-canonical spellings all declined')
}

// And the shapes it MUST call canonical — the regression guard on the
// other side, so a conservative drift cannot silently forfeit the win.
const must_be_canonical = [
	'[k]',
	'[k 1]',
	'[k -1]',
	'[k 0.53]',
	'[k 10.50]',
	'[k true]',
	'[k false]',
	'[k null]',
	"[k 'abc']",
	'[k "abc"]', // via the delimiter rewrite
	'[k "it\'s"]', // content has a `\'`, so `"…"` IS canonical
	'[k :s 1]',
	'[k :s 1 :t "x"]',
	'[k [n 1] [m 2]]',
	'[user :id 0 :name "alice" :active true :ratio 0.5]',
]

fn test_documented_canonical_shapes() {
	for src in must_be_canonical {
		bytes := src.bytes()
		sc := cx.scan_child_canonical(bytes, 0) or {
			assert false, 'expected canonical, but the scan DECLINED: ${src}'
			continue
		}
		assert sc.canonical, 'expected canonical, got not-canonical: ${src}'
		emitted := cx.apply_rewrites(bytes[..sc.end], 0, sc.rewrites)
		doc := cx.parse(src) or {
			assert false, 'unparseable: ${src}'
			continue
		}
		want := code.render_canonical(doc.elements[0])
		assert emitted == want, 'emit mismatch for ${src}: got ${emitted}, renderer says ${want}'
	}
	println('[child-scan] ${must_be_canonical.len} documented canonical shapes all emit the renderer\'s bytes')
}

// ── the resolve-is-a-no-op obligation ─────────────────────────────────
//
// Soundness (above) proves a certified span PARSES. That is only half of
// what PASS 1 did: it also ran `resolve_namespaces` +
// `validate_reserved_ns_bindings` per child, and either of those can
// REFUSE. A certified child skips them, so the subset's exclusions have
// to make that skip lossless — every certified child must resolve
// without error AND without its image moving.
//
// This is the half that would fail silently. An unsound parse shows up
// as a crash somewhere; a lost refusal shows up as an input the
// streaming path accepts and the materializing path rejects, which is
// the exact divergence PASS 1 exists to prevent.

// resolve_is_noop mirrors code/streamed_input.v's streamed_input_resolve:
// wrap the child under a synthetic namespace-free root, resolve, unwrap.
// Returns false if it errors or if the child's image moved.
fn resolve_is_noop(span string) bool {
	doc := cx.parse(span) or { return false }
	if doc.elements.len != 1 {
		return false
	}
	child := doc.elements[0]
	before := code.render_canonical(child)
	mut sdoc := cx.Document{
		elements: [
			cx.Node(cx.Element{
				name:  'root'
				items: [child]
			}),
		]
	}
	cx.resolve_namespaces(mut sdoc)
	cx.validate_reserved_ns_bindings(sdoc) or { return false }
	wrapped := sdoc.elements[0]
	if wrapped !is cx.Element {
		return false
	}
	el := wrapped as cx.Element
	if el.items.len != 1 {
		return false
	}
	return code.render_canonical(el.items[0]) == before
}

fn test_certified_children_resolve_to_a_noop() {
	mut checked := 0
	files := os.ls(conformance_dir()) or {
		assert false, 'cannot list conformance dir'
		return
	}
	for f in files {
		if !f.ends_with('.cxd') {
			continue
		}
		path := os.join_path(conformance_dir(), f)
		for c in fixtures.load_fixtures(path) {
			src := c.sections['in_cx'].trim_space()
			if src == '' || src == '[ignored]' || src == '[empty]' {
				continue
			}
			end := certified_span(src) or { continue }
			checked++
			assert resolve_is_noop(src[..end]), 'certified child does NOT resolve to a no-op — ' +
				'PASS 1 would lose a refusal or a rewrite\n  ${f}/${c.name}\n  span: ${src[..end]}'
		}
	}
	for seed in mutation_seeds {
		end := certified_span(seed) or { continue }
		checked++
		assert resolve_is_noop(seed[..end]), 'certified seed does not resolve to a no-op: ${seed}'
	}
	for i in 0 .. 500 {
		r := gate_record(i)
		end := certified_span(r) or { continue }
		checked++
		assert resolve_is_noop(r[..end]), 'certified gate record does not resolve to a no-op: ${r}'
	}
	assert checked > 300, 'only ${checked} certified spans checked — corpus coverage collapsed'
	println('[child-scan] resolve no-op: ${checked} certified spans, 0 movements')
}

// ── the root-namespace precondition ───────────────────────────────────

fn test_top_namespace_free_gate() {
	free := cx.open_top_level_children('[users [user :id 1]]') or {
		assert false, 'open failed: ${err.msg()}'
		return
	}
	assert free.top.top_is_namespace_free()

	bound := cx.open_top_level_children('[users xmlns="http://x" [user :id 1]]') or {
		assert false, 'open failed: ${err.msg()}'
		return
	}
	assert !bound.top.top_is_namespace_free(), 'a default-namespace root must block certification'

	lang := cx.open_top_level_children('[users cx:lang="en" [user :id 1]]') or {
		assert false, 'open failed: ${err.msg()}'
		return
	}
	assert !lang.top.top_is_namespace_free(), 'a cx:lang root must block certification'
}

// ── #804 leg 8: the RewriteSet SPILL path ─────────────────────────────────
//
// Leg 8 moved a record's rewrite offsets from a heap `[]int` into an inline
// `[8]int` with a heap spill past that. The inline half is covered by every
// other case in this file, because the §11.4.4 gate record carries two
// strings = four offsets and never comes close to the boundary.
//
// THAT IS EXACTLY THE PROBLEM. The spill branch is unreachable from the
// corpus that motivated the change, so it could be wrong in every build and
// nothing here would notice — the shape this issue has already been bitten by
// three times (#851). These cases exist to reach it deliberately: at the
// boundary, one past it, and far past it, with the offsets checked in ORDER
// (a spill that appends correctly but reads back out of order still corrupts
// the emitted image, and `apply_rewrites` would happily produce plausible
// wrong bytes).
fn test_rewrite_set_spill_boundary() {
	// n quoted strings => 2n rewrite offsets. cap is 8, so n=4 exactly fills
	// the inline buffer, n=5 spills by two, n=12 spills heavily.
	for n in [1, 3, 4, 5, 6, 12] {
		mut src := '[rec'
		for i in 0 .. n {
			src += ' :k${i} "v${i}"'
		}
		src += ']'
		bytes := src.bytes()
		sc := cx.scan_child_canonical(bytes, 0) or {
			assert false, 'leg 8 spill: scan declined a plain quoted-string record (n=${n}): ${src}'
			continue
		}
		assert sc.canonical, 'leg 8 spill: n=${n} should certify canonical: ${src}'
		assert sc.rewrites.len == 2 * n,
			'leg 8 spill: n=${n} must record ${2 * n} offsets, got ${sc.rewrites.len}'

		// Offsets must come back STRICTLY INCREASING — scan order. An
		// inline/spill read that returns them out of order still renders
		// well-formed output, just wrong output.
		for i in 1 .. sc.rewrites.len {
			assert sc.rewrites.get(i) > sc.rewrites.get(i - 1),
				'leg 8 spill: offsets out of order at i=${i} (n=${n}): ' +
				'${sc.rewrites.get(i - 1)} then ${sc.rewrites.get(i)}'
		}
		// Every recorded offset must actually point at a `"` in the source.
		for i in 0 .. sc.rewrites.len {
			off := sc.rewrites.get(i)
			assert off >= 0 && off < bytes.len,
				'leg 8 spill: offset ${off} out of range (n=${n})'
			assert bytes[off] == `"`,
				'leg 8 spill: offset ${off} points at `${bytes[off].ascii_str()}`, not a quote (n=${n})'
		}
		// And the end-to-end obligation this all exists for: the emitted
		// image must equal what the real renderer produces.
		emitted := cx.apply_rewrites(bytes[..sc.end], 0, sc.rewrites)
		doc := cx.parse(src) or {
			assert false, 'leg 8 spill: n=${n} did not parse: ${src}'
			continue
		}
		want := code.render_canonical(doc.elements[0])
		assert emitted == want,
			'leg 8 spill: emitted image diverges from the renderer at n=${n}\n' +
			'  src     : ${src}\n  emitted : ${emitted}\n  renderer: ${want}'
	}
}

// ── source: vcx/tests/lazy_record_differential_test.v ──
// lazy_record_differential_test — the safety instrument for #804 leg 2's
// lazy record (`vcx/cx/lazy_record.v`), and the thing ruling 1a traded for.
//
// THE SITUATION THIS EXISTS FOR. `cx.Node` gained a 28th variant, and the
// audit measured that the compiler will not police it: 1,323 of the tree's
// 1,341 non-test `is Element` sites are `if`-form tag tests that silently
// take the else branch. An unforced lazy record reaching one of them does
// not crash — it reads as *not an element*, a plausible wrong answer on the
// most identity-sensitive code in the system. Only ~18 sites sit in
// exhaustive `match` position; adding the variant produced exactly three
// compile errors, which is the measurement confirming itself.
//
// So leg 2's forcing discipline cannot be sound BY CONSTRUCTION, and ruling
// 1a did not pretend otherwise. It is sound by DIFFERENTIAL:
//
//     for every program and input, the bytes rendered with lazy records
//     enabled == the bytes rendered with them disabled
//
// With the mechanism off, the streamed walk materialises every child at
// creation and no LazyRecord is ever built — that arm is the engine as it
// was before leg 2. So any difference between the two arms is a forcing bug
// and nothing else: a site that observed a lazy record without forcing it.
//
// It runs IN-PROCESS, both arms in one binary, on every suite run. A
// differential that only fires when someone remembers to build twice is
// most of the way back to no differential at all.
//
// WHAT TO DO IF THIS GOES RED. Do not add a case-specific force to make it
// pass. The red means some site read a lazy record's structure without
// forcing; find that site. The failing program tells you which shape
// reached it.

// DrSink accumulates the streamed chunks.
//
// It is a HEAP struct captured by pointer, and that detail is load-bearing:
// capturing a `strings.Builder` by value in the sink closure silently drops
// every chunk, so `dr_eval` returns "" for everything and the whole file
// compares "" against "" and passes. That is exactly what the first version
// of this test did, and the only reason it was caught is the break-test
// below — deleting a real forcing site and confirming this goes RED. Do that
// again after any change to how the bytes are captured.
@[heap]
struct DrSink {
mut:
	chunks []string
}

// dr_eval renders one program over one input through the streaming API,
// returning the exact bytes a caller would receive.
fn dr_eval(input string, program string) !string {
	sk := &DrSink{}
	sink := fn [sk] (chunk string) ! {
		unsafe {
			sk.chunks << chunk
		}
	}
	code.eval_code_streaming(input, program, 'text', sink)!
	return sk.chunks.join('')
}

// dr_both evaluates the same work with lazy records on and off, and returns
// the two byte strings. The switch is restored either way.
fn dr_both(input string, program string) (string, string) {
	code.set_lazy_records_off(false)
	lazy := dr_eval(input, program) or { 'ERR: ${err.msg()}' }
	code.set_lazy_records_off(true)
	strict := dr_eval(input, program) or { 'ERR: ${err.msg()}' }
	code.set_lazy_records_off(false)
	return lazy, strict
}

fn dr_assert_agree(input string, program string, origin string) {
	lazy, strict := dr_both(input, program)
	assert lazy == strict, 'LAZY/STRICT DIVERGENCE — a site read a lazy record without forcing it\n' +
		'  origin  : ${origin}\n  program : ${program}\n' +
		'  lazy    : ${lazy}\n  strict  : ${strict}'
}

// dr_assert_live refuses a program that FAILS on both arms.
//
// Two arms that both error agree perfectly and test nothing. This file has
// been bitten by exactly that twice — first by a sink that dropped every
// chunk (both arms ""), then by three programs written with `:take` / `:drop`
// / `:where` slot spellings that the for-comprehension parser rejects, so
// both arms returned the same parse error and passed. A mis-spelled program
// in a differential is indistinguishable from a passing one unless something
// checks, so this checks.
//
// It is deliberately about the BASELINE corpus only: the refusal-parity test
// below feeds inputs that are SUPPOSED to error, and asserting liveness there
// would be wrong.
fn dr_assert_live(input string, program string) {
	lazy, _ := dr_both(input, program)
	assert !lazy.starts_with('ERR:'),
		'DEAD PROGRAM — it fails on both arms, so it agrees vacuously and tests nothing:\n' +
		'  program : ${program}\n  error   : ${lazy}'
	assert lazy.len > 0,
		'DEAD PROGRAM — it produces no bytes on either arm:\n  program : ${program}'
}

// ── the corpus ────────────────────────────────────────────────────────

// dr_records builds a JSON-shape input of `n` records — the §11.4.4 shape,
// the one the fast path is for.
//
// Each record carries a NESTED CHILD ELEMENT as well as its slots, and that
// is not decoration. Slots (`:name "a"`) are not children, so `$u/name`
// selects nothing — slots are NOT path-readable at all (`$u/name` and
// `$u@name` both yield `()`; only real attributes answer `/@k`) — and a
// program written that way yields empty on BOTH arms —
// it agrees vacuously and exercises no forcing at all. The first version of
// this corpus was slots-only, which is why removing a real forcing site left
// it green. `[tag …]` gives the path programs something to actually reach.
fn dr_records(n int) string {
	mut b := strings.new_builder(256)
	b.write_string('[users\n')
	for i in 0 .. n {
		active := if (i & 1) == 0 { 'true' } else { 'false' }
		b.write_string('  [user :id ${i} :name "n-${i}" :active ${active} :ratio 0.${i} [tag :k ${i} :label "t-${i}"]]\n')
	}
	b.write_string(']\n')
	return b.str()
}

// The programs. Each one is here because it reaches the bound value a
// DIFFERENT way — the point is coverage of how a record can be observed,
// not of how many records there are.
const dr_programs = [
	// pure pass-through: the record is never inspected at all. This is the
	// shape the whole architecture exists for, and the one where a forcing
	// bug would be invisible to a test that only checked "does it run".
	'[?for [in \$u \$doc/user] [yield \$u]]',
	// navigation forces: a path step is a structural read. These reach the
	// NESTED CHILD, not the slots — a slot step selects nothing and would
	// agree vacuously (see dr_records).
	'[?for [in \$u \$doc/user] [yield \$u/tag]]',
	'[?for [in \$u \$doc/user] [yield [\$count \$u/tag]]]',
	'[?for [in \$u \$doc/user] [yield [wrap \$u/tag]]]',
	// the value flows into a builtin as a whole — the escape route the
	// audit identified, where a path-less read hands the record to
	// arbitrary code.
	'[?for [in \$u \$doc/user] [yield [\$count \$u]]]',
	// ...and into a comparison, and a guard.
	'[?for [in \$u \$doc/user] [where [\$exists \$u/tag]] [yield \$u]]',
	'[?for [in \$u \$doc/user] [where [\$exists \$u/tag]] [yield \$u/tag]]',
	// bound to another name first, then navigated — aliasing, which is
	// how a "does this program touch $u" analysis would have been fooled.
	'[?for [in \$u \$doc/user] [= \$v \$u] [yield \$v/tag]]',
	'[?for [in \$u \$doc/user] [= \$v \$u] [yield \$v]]',
	// the record inside a constructed element — carried, not inspected.
	'[?for [in \$u \$doc/user] [yield [wrapped \$u]]]',
	// limits and skips, which change WHICH records are forced.
	'[?for [in \$u \$doc/user] [take 3] [yield \$u]]',
	'[?for [in \$u \$doc/user] [drop 2] [yield \$u]]',
	'[?for [in \$u \$doc/user] [take 2] [yield \$u/tag]]',
	// two-step plan: steps INTO the record, so it forces and must also
	// pay the resolve it skipped.
	'[?for [in \$n \$doc/user/tag] [yield \$n]]',
	// reserved position binding alongside a lazy value.
	'[?for [in \$u \$doc/user] [yield [p \$_position]]]',
	// ── #845: the [?map] lane, which hands a lazy record to a CLOSURE ──
	// A new escape route, and the reason these are here rather than assumed
	// covered: the [?for] programs above reach the record through clause
	// machinery this project controls, while `:using` hands it to an
	// arbitrary user closure. Every observation route is re-run through that
	// boundary. At corpus sizes 1 and 2 these also exercise the DECLINING
	// side of the deferred commit (a 1-match walk never commits), so both
	// halves of the refusal-parity discipline are differentiated.
	//
	// pure pass-through THROUGH a closure — never inspected.
	'[?map \$doc/user [using [?fn (\$u) \$u]]]',
	// navigation inside the closure body forces.
	'[?map \$doc/user [using [?fn (\$u) \$u/tag]]]',
	// the whole record into a builtin, from inside the closure.
	'[?map \$doc/user [using [?fn (\$u) [\$count \$u]]]]',
	// carried into a construction rather than inspected.
	'[?map \$doc/user [using [?fn (\$u) [wrapped \$u]]]]',
	// two-step plan on the map lane: steps INTO the record, so it forces and
	// must also pay the resolve the one-step form skips.
	'[?map \$doc/user/tag [using [?fn (\$n) \$n]]]',
]

fn test_lazy_and_strict_agree_over_the_record_shape() {
	// The instrument must be exercising the lazy arm. Without this the whole
	// file could pass by comparing the strict path against itself — the
	// vacuous-green shape this project keeps meeting.
	code.set_lazy_records_off(false)
	assert code.lazy_records_active(), 'the lazy arm is disabled — this differential would be vacuous'

	// The bytes must actually exist. A sink that silently drops its chunks
	// makes every comparison "" == "" and the file passes green over
	// nothing — which is what the first version of this test did.
	probe := dr_eval(dr_records(40), '[?for [in \$u \$doc/user] [yield \$u]]') or {
		assert false, 'baseline eval failed: ${err.msg()}'
		return
	}
	assert probe.len > 100, 'the harness captured ${probe.len} bytes — the sink is dropping chunks and this differential is vacuous'
	assert probe.contains('[user'), 'the harness captured bytes that are not the records: ${probe#[..80]}'

	// Every program must actually RUN before its agreement means anything.
	live_input := dr_records(40)
	for p in dr_programs {
		dr_assert_live(live_input, p)
	}

	for n in [1, 2, 3, 5, 40] {
		input := dr_records(n)
		for p in dr_programs {
			dr_assert_agree(input, p, '${n} records')
		}
	}
	println('[lazy-diff] ${dr_programs.len} programs x 5 corpus sizes, lazy == strict')
}

// Inputs that DECLINE the certified subset, so the walk mixes lazy and
// materialised children in one pass. A record that forces beside one that
// does not is where an ordering or aliasing bug would show up, and it is not
// reachable from the uniform corpus above.
const dr_mixed_inputs = [
	// a QName child declines (namespaces leave the subset), its neighbours
	// certify.
	'[users [user :id 1 :name "a"] [ns:user :id 2 :name "b"] [user :id 3 :name "c"]]',
	// an escape-bearing string declines.
	'[users [user :id 1 :name "a"] [user :id 2 :name "b\\tc"] [user :id 3 :name "d"]]',
	// bare body text declines.
	'[users [user :id 1 :name "a"] [user hello] [user :id 3 :name "c"]]',
	// a nested child element inside one record.
	'[users [user :id 1 :name "a"] [user :id 2 [inner :k 1]] [user :id 3 :name "c"]]',
	// attributes are certified but never canonical (the renderer emits
	// values bare when safe), so these force at render.
	'[users [user id=1 name="a"] [user id=2 name="b"] [user id=3 name="c"]]',
	// canonical single-quoted source — already its own image, no rewrite.
	"[users [user :id 1 :name 'a'] [user :id 2 :name 'b'] [user :id 3 :name 'c']]",
	// content containing a quote, so `\"…\"` IS the canonical form.
	'[users [user :id 1 :name "o\'hara"] [user :id 2 :name "b"] [user :id 3 :name "c"]]',
	// negative zero and leading zeros: well-formed, NOT canonical.
	'[users [user :id -0 :name "a"] [user :id 2 :name "b"] [user :id 3 :name "c"]]',
	// decimals carried verbatim, trailing zeros included.
	'[users [user :id 1 :ratio 10.50] [user :id 2 :ratio 0.10] [user :id 3 :ratio 1.0]]',
]

fn test_lazy_and_strict_agree_when_the_walk_is_mixed() {
	code.set_lazy_records_off(false)
	for input in dr_mixed_inputs {
		for p in dr_programs {
			dr_assert_agree(input, p, 'mixed: ${input#[..40]}')
		}
	}
	println('[lazy-diff] ${dr_mixed_inputs.len} mixed inputs x ${dr_programs.len} programs, lazy == strict')
}

// A record forced TWICE must parse once and answer identically both times.
// Without the shared memo cell this is a silent throughput regression
// against the materialising path rather than an improvement — two reads of
// one record would parse it twice.
fn test_repeated_reads_agree() {
	code.set_lazy_records_off(false)
	input := dr_records(6)
	for p in [
		'[?for [in \$u \$doc/user] [yield [pair \$u/tag \$u/tag]]]',
		'[?for [in \$u \$doc/user] [yield [triple \$u/tag \$u/tag \$u/tag]]]',
		'[?for [in \$u \$doc/user] [where [\$exists \$u/tag]] [yield [pair \$u/tag \$u/tag]]]',
	] {
		dr_assert_agree(input, p, 'repeated reads')
	}
}

// Inputs the fast path REFUSES must refuse identically on both arms —
// success/refusal parity is the property PASS 1 exists for, and a lazy
// record must not change which inputs are accepted.
fn test_refusals_agree() {
	code.set_lazy_records_off(false)
	for input in [
		'[users [user :id 1 :name "a"] [user :id 2 :name "b"',   // unterminated
		'[users [user :id 1 :name "a"] [cx:reserved x=1]]',      // reserved ns
		'[users [user :id 1] [user :id 2]] [extra]',             // trailing content
		'[users [user :id 1 :name "a"] &anchor [user :id 2]]',   // anchors decline
	] {
		for p in dr_programs {
			dr_assert_agree(input, p, 'refusal: ${input#[..30]}')
		}
	}
	println('[lazy-diff] refusal parity holds on both arms')
}

// ── source: vcx/tests/cx_ast_scaling_test.v ──
// cx_ast_scaling_test.v — the #941 regression guard.
//
// cx:ast was quadratic in source size (measured 2026-08-23: 3.4 KB →
// 3.1 ms, 34.9 KB → 147 ms, 354 KB → 5,178 ms; ~1670x time for 100x
// input). The mechanism was json_str (emitter_json.v): per-byte string
// `+=` on an immutable V string reallocates and copies the whole
// accumulator each step — O(n²) — and cx_mod_ast feeds it whole verbatim
// module spans via json_str_public. Fixed with a strings.Builder
// (354 KB: 5,178 ms → ~4.5 ms).
//
// This guard pins the MECHANISM at its seam: escape an S-byte and an
// 8S-byte string and assert the process-CPU ratio stays linear-ish
// (<= 24; linear ≈ 8, the old quadratic ≈ 64). Relative, never absolute
// wall time — the parse_amplification_test calibration showed absolute
// ceilings gate the machine's mood, not the algorithm; and process CPU
// via C.clock() stays honest under a parallel suite where wall does not.
// Correctness of the escaping itself is asserted alongside (the fix must
// not change one byte of output).

fn C.clock() i64

fn escape_input(n int) string {
	// Realistic span content: mostly plain bytes with periodic escapes
	// (quotes, backslashes, newlines) so both match arms run.
	base := 'plain text with "quotes" and \\ backslash and\n\tcontrol\r chars '
	mut b := []u8{cap: n + base.len}
	for b.len < n {
		b << base.bytes()
	}
	return b[..n].bytestr()
}

fn cpu_of_escape(s string, reps int) i64 {
	mut best := i64(9223372036854775807)
	for _ in 0 .. reps {
		t0 := C.clock()
		out := cx.json_str_public(s)
		t1 := C.clock()
		assert out.len > s.len // escapes present → strictly longer, +2 quotes
		d := t1 - t0
		if d < best {
			best = d
		}
	}
	return best
}

fn test_json_str_scales_linearly() {
	// Byte-exactness first: the guard must not outlive a broken escape.
	assert cx.json_str_public('a"b\\c\nd\te\rf') == '"a\\"b\\\\c\\nd\\te\\rf"'
	assert cx.json_str_public('\x01') == '"\\u0001"'
	assert cx.json_str_public('') == '""'

	small := escape_input(131072) // 128 KB
	big := escape_input(1048576) // 1 MB — 8x
	// Warm both paths once before timing.
	_ := cx.json_str_public(small)
	t_small := cpu_of_escape(small, 3)
	t_big := cpu_of_escape(big, 3)
	// Guard against a zero-tick small measurement on a fast machine:
	// clock() granularity can floor tiny runs. Repeat the small input
	// enough times to register at least ~50 ticks.
	if t_small < 50 {
		mut reps_ticks := i64(0)
		t0 := C.clock()
		for _ in 0 .. 32 {
			_ := cx.json_str_public(small)
		}
		reps_ticks = C.clock() - t0
		avg := if reps_ticks > 0 { reps_ticks / 32 } else { i64(1) }
		ratio := f64(t_big) / f64(avg)
		println('json_str scaling (averaged small): 128KB=${avg} ticks 1MB=${t_big} ticks ratio=${ratio:.1f} (linear ~8, quadratic ~64)')
		assert ratio <= 24.0, 'json_str is superlinear again (#941): 8x input cost ${ratio:.1f}x CPU'
		return
	}
	ratio := f64(t_big) / f64(t_small)
	println('json_str scaling: 128KB=${t_small} ticks 1MB=${t_big} ticks ratio=${ratio:.1f} (linear ~8, quadratic ~64)')
	assert ratio <= 24.0, 'json_str is superlinear again (#941): 8x input cost ${ratio:.1f}x CPU'
}

// ── source: vcx/tests/parse_amplification_test.v ──
// parse_amplification_test.v — the LIM-2 amplification gate
// (spec/03-approved/core/limits.md; ruling LIM-2, owner 2a, 2026-08-20).
//
// limits.md §4's whole posture rests on ONE claim: parse cost is LINEAR
// in input bytes, so every quantity an attacker controls is a quantity
// the embedder already holds in hand. This gate PINS that claim so it is
// a tested property, not an intention — a future parser change that
// introduces superlinear time or node amplification goes red here, which
// a fixed cap could never do.
//
// Method: for each adversarial shape, parse at N and 4N bytes and assert
//   nodes(4N) <= 4 * nodes(N) + 64       (no node amplification — HARD)
// and PRINT the CPU-time ratio as a diagnostic (advisory, never asserted).
//
// Why time is advisory: calibration 2026-08-20 measured the parse
// ALGORITHM linear (-gc none: 1.9-2.3x per byte-doubling on every
// shape), but under the shipped collector both wall time (suite load)
// and process CPU (parallel-mark cost growing with live heap — up to
// 14x for 4x bytes on the tiny-siblings shape) are superlinear at MB
// scale for reasons that are collector properties, not parser
// properties. A time assertion here can only gate the collector's
// mood. The node bound is deterministic, load-immune, and catches the
// attack class the gate exists for (a construction that mints more
// work per byte); the printed ratio keeps drift visible in logs.
// Shapes cover the historically dangerous inputs: attr-heavy elements,
// many tiny siblings, deep-but-capped nesting runs, long bare scalars,
// entity-ref-dense bodies, and comment-dense text.

fn count_nodes(n cx.Node) int {
	mut total := 1
	if n is cx.Element {
		total += n.attrs.len
		for c in n.items {
			total += count_nodes(c)
		}
	}
	return total
}

fn doc_nodes(d cx.Document) int {
	mut total := 0
	for e in d.elements {
		total += count_nodes(e)
	}
	return total
}

// build one adversarial document of roughly `target` bytes from a unit.
fn build(unit string, target int) string {
	reps := target / unit.len + 1
	mut sb := []string{cap: reps + 2}
	sb << '[root'
	for _ in 0 .. reps {
		sb << unit
	}
	sb << ']'
	return sb.join('\n')
}

fn measure(src string) (i64, int) {
	start := C.clock()
	d := cx.parse(src) or { panic('amplification-gate input must parse: ${err}') }
	elapsed := C.clock() - start
	return elapsed, doc_nodes(d)
}

fn assert_linear(name string, unit string) {
	n := 262144 // 256 KiB base
	small := build(unit, n)
	big := build(unit, n * 4)
	// warm both paths once so allocator/page effects don't skew trial 1
	cx.parse(small) or { panic(err) }
	cx.parse(big) or { panic(err) }
	// median-of-5 per size: min is noise-prone in EITHER direction here
	// (one lucky-fast small sample fakes a superlinear ratio)
	mut ts_all := []i64{}
	mut tb_all := []i64{}
	mut nodes_small := 0
	mut nodes_big := 0
	for _ in 0 .. 5 {
		ts, ns := measure(small)
		ts_all << ts
		nodes_small = ns
		tb, nb := measure(big)
		tb_all << tb
		nodes_big = nb
	}
	ts_all.sort()
	tb_all.sort()
	t_small := ts_all[2]
	t_big := tb_all[2]
	// advisory CPU-ratio diagnostic (linear predicts ~4x; collector cost
	// inflates it at MB scale — see the header)
	ratio_x10 := if t_small > 0 { t_big * 10 / t_small } else { 0 }
	println('  amplification[${name}]: cpu ${t_small} -> ${t_big} ticks @4x bytes (${ratio_x10 / 10}.${ratio_x10 % 10}x, advisory)')
	// node amplification: 4x bytes may yield at most ~4x nodes — HARD
	assert nodes_big <= 4 * nodes_small + 64, '${name}: node amplification — ${nodes_small} @1x vs ${nodes_big} @4x'
}

fn test_attr_heavy_elements_stay_linear() {
	assert_linear('attr-heavy', '[e a1=1 a2=2 a3=3 a4=4 a5=5 a6=6 a7=7 a8=8]')
}

fn test_many_tiny_siblings_stay_linear() {
	assert_linear('tiny-siblings', '[x][y][z]')
}

fn test_capped_nesting_runs_stay_linear() {
	// nesting depth 32 (under the 64 cap), repeated in sequence
	mut unit := ''
	for _ in 0 .. 32 {
		unit += '[n '
	}
	unit += '1'
	for _ in 0 .. 32 {
		unit += ']'
	}
	assert_linear('nesting-runs', unit)
}

fn test_long_bare_scalars_stay_linear() {
	assert_linear('bare-scalars', '[s abcdefghijklmnopqrstuvwxyz0123456789]')
}

fn test_entity_dense_bodies_stay_linear() {
	// entity refs parse to nodes, never expand (limits.md §3) — density
	// must not amplify
	assert_linear('entity-dense', '[t a &amp; b &lt; c &gt; d]')
}

fn test_comment_dense_text_stays_linear() {
	assert_linear('comment-dense', '[; a comment that the parser must skip ][c 1]')
}

fn test_max_input_bytes_refuses_typed() {
	src := '[a 1]'
	// under the bound: parses
	d := cx.parse_limited(src, cx.ParseLimits{ max_input_bytes: 1024 }) or {
		panic('under-bound parse must succeed: ${err}')
	}
	assert d.elements.len == 1
	// over the bound: typed refusal naming both numbers and the spec home
	cx.parse_limited(src, cx.ParseLimits{ max_input_bytes: 3 }) or {
		assert err.msg().contains('max_input_bytes'), 'refusal must name the guard: ${err.msg()}'
		assert err.msg().contains('limits.md'), 'refusal must cite the spec home: ${err.msg()}'
		return
	}
	panic('over-bound parse must refuse')
}

fn test_zero_means_unbounded() {
	d := cx.parse_limited('[a 1]', cx.ParseLimits{}) or { panic(err) }
	assert d.elements.len == 1
}
